import{_ as t,a0 as o,w as r,s as d,ao as l,I as i,x as a,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"讓 YAML 變得像它看起來一樣簡單 | LCTT x X-CMD","titleTemplate":false,"description":"讓 YAML 變得像它看起來一樣簡單 | LCTT (202110) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"讓 YAML 變得像它看起來一樣簡單 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"讓 YAML 變得像它看起來一樣簡單 | LCTT (202110) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202110/20210930 Make YAML as easy as it looks","title":"讓 YAML 變得像它看起來一樣簡單","tag":"202110","desc":""},"relativePath":"202110/20210930 Make YAML as easy as it looks.md","filePath":"[post].md"}'),h={name:"202110/20210930 Make YAML as easy as it looks.md"};function u(k,s,g,b,A,M){const n=o("Link");return r(),d("div",null,[s[23]||(s[23]=l(`<h1 id="讓-yaml-變得像它看起來一樣簡單" tabindex="-1">讓 YAML 變得像它看起來一樣簡單 <a class="header-anchor" href="#讓-yaml-變得像它看起來一樣簡單" aria-label="Permalink to “讓 YAML 變得像它看起來一樣簡單”">​</a></h1><blockquote><p>YAML 看起來很簡單，為什麼它這麼難寫呢？瞭解成功使用 YAML 的兩個秘訣。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202110/02/101824shamurmpvldpu29a.jpg" alt=""></p><p>如果你曾經嘗試過寫 YAML，你可能一開始會對它看起來很容易感到高興。乍一看，經常用於配置文件、Ansible 劇本和普通文件資料庫的 YAML 看起來就像購物清單一樣直觀。然而，YAML 的結構中有很多細微的差別，它隱藏着一個危險的秘密：YAML 實際上是一種高度精確、結構化和令人驚訝的嚴格語言。好消息是，你只需要瞭解兩件事就可以知道 YAML 的工作原理。</p><p>關於 YAML 的真相是，YAML 中只有兩種數據結構：<ruby>序列<rt>sequence</rt></ruby>和<ruby>映射<rt>mapping</rt></ruby>。這是兩個花哨的名字，你會發現它代表了你非常熟悉的概念。這篇文章解釋了這兩種結構，更重要的是，介紹了它們是如何協同工作，使 YAML 成為表示你所關心的數據的強大方式。</p><h3 id="yaml-序列" tabindex="-1">YAML 序列 <a class="header-anchor" href="#yaml-序列" aria-label="Permalink to “YAML 序列”">​</a></h3><p>YAML 序列是一個列表。在其最簡單的形式中，每行有一個項目，每行以破折號和空格開始。</p><p>下面是一個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>- Linux</span></span>
<span class="line"><span>- BSD</span></span>
<span class="line"><span>- Illumos</span></span></code></pre></div><p>不同的語言有不同的方式來表示這種數據。例如，在 Python 中，同一個列表可以寫成 <code>[&#39;Linux&#39;, &#39;BSD&#39;, &#39;Illumos&#39;]</code>。當你在現實生活中寫一個列表時，例如在你去買菜之前，你寫的可能近似於 YAML 序列。</p><h3 id="yaml-映射" tabindex="-1">YAML 映射 <a class="header-anchor" href="#yaml-映射" aria-label="Permalink to “YAML 映射”">​</a></h3><p>YAML 映射是一個關鍵術語與該術語的定義相結合。在其他語言中，映射被稱為“鍵值對”或“詞典”。</p><p>這裏有一個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>Kernel: Linux</span></span>
<span class="line"><span>CPU: AMD</span></span>
<span class="line"><span>RAM: &#39;16 GB&#39;</span></span></code></pre></div>`,14)),i("p",null,[s[1]||(s[1]=a("不同的語言有不同的方式來表示這種數據。",-1)),e(n,{href:"https://opensource.com/article/21/3/dictionary-values-python"},{default:p(()=>[...s[0]||(s[0]=[a("在 Python 中",-1)])]),_:1}),s[2]||(s[2]=a("，例如，同樣的數據可以寫成 ",-1)),s[3]||(s[3]=i("code",null,'{"Kernel": "Linux", "CPU": "AMD", "RAM": "16 GB"}',-1)),s[4]||(s[4]=a("。在現實生活中，你可能會使用這種結構來計劃，例如，與朋友的遊戲之夜。一個朋友報名帶零食，另一個報名帶一副牌，另一個報名帶一個棋盤遊戲，等等。",-1))]),s[24]||(s[24]=l(`<h3 id="組合序列和映射" tabindex="-1">組合序列和映射 <a class="header-anchor" href="#組合序列和映射" aria-label="Permalink to “組合序列和映射”">​</a></h3><p>你現在知道 YAML 的語法了。序列和映射是 YAML 中僅有的兩種構件，你想在 YAML 中表示的任何東西都可以放在序列或映射中。</p><p>或者同時使用這二者！</p><p>是的，序列和映射可以被組合和嵌套，這就是 YAML 看起來很直觀，但同時又感覺很複雜的原因之一。不過，只有四種可能的組合，一旦你學會如何看它們，YAML 就會覺得像它看起來一樣簡單。</p><h3 id="序列的映射" tabindex="-1">序列的映射 <a class="header-anchor" href="#序列的映射" aria-label="Permalink to “序列的映射”">​</a></h3><p>當你想讓一個鍵項有許多值時，你可以使用一個序列的映射。也就是説，你從一個映射（鍵）開始，但是給值一個列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>Linux:</span></span>
<span class="line"><span>  - Fedora</span></span>
<span class="line"><span>  - Slackware</span></span>
<span class="line"><span>BSD:</span></span>
<span class="line"><span>  - FreeBSD</span></span>
<span class="line"><span>  - NetBSD</span></span></code></pre></div><p>在這個示例代碼中，<code>Linux</code> 是第一個鍵，它的值是一個序列，其中包含 <code>Fedora</code> 和 <code>Slackware</code>。第二個鍵是 <code>BSD</code>，它的值是一個序列，包含 <code>FreeBSD</code> 和 <code>NetBSD</code>。</p><h3 id="映射的映射" tabindex="-1">映射的映射 <a class="header-anchor" href="#映射的映射" aria-label="Permalink to “映射的映射”">​</a></h3><p>當你想讓一個鍵項的值中既有鍵又有值時，你可以使用映射的映射。也就是説，你從一個映射（鍵）開始，但是給值另一個映射。</p><p>這可能有點欺騙性，但它揭示了 YAML 中使用特定術語的原因：因為你只不過是創建了一個映射的列表，並不意味着你創建了一個序列。這裏是一個映射的映射：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>Desktop:</span></span>
<span class="line"><span>  CPU: RISC-V</span></span>
<span class="line"><span>  RAM: &#39;32 GB&#39;</span></span>
<span class="line"><span>Laptop:</span></span>
<span class="line"><span>  CPU: AMD</span></span>
<span class="line"><span>  RAM: &#39;16 GB&#39;</span></span></code></pre></div><p>對大多數人來説，這看起來像一個列表。而且從技術上講，它是一個列表。但重要的是要認識到，它不是 YAML 序列。它是一個映射，其中包含映射。作為半個 YAML 專家，你可以從明顯缺少破折號的地方看出區別。</p><p>在 Ansible 劇本的所有結構中，我發現這個結構最容易欺騙人。作為人類，我們喜歡列表，當我們看到一個數據結構 <em>在字面上</em> 是列表時，大多數人會把它當成 YAML 序列。但是在 YAML 中，雖然序列是列表，但是列表並不總是序列。</p><h3 id="序列的序列" tabindex="-1">序列的序列 <a class="header-anchor" href="#序列的序列" aria-label="Permalink to “序列的序列”">​</a></h3><p>就像你可以嵌套映射一樣，你可以將一個序列嵌套到一個序列中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>- [Linux, FreeBSD, Illumos]</span></span>
<span class="line"><span>- [YAML, XML, JSON]</span></span></code></pre></div><p>這可能是我在 YAML 的實際使用中遇到的最不常見的數據結構，但有時你需要一個列表的列表。</p><h3 id="映射的序列" tabindex="-1">映射的序列 <a class="header-anchor" href="#映射的序列" aria-label="Permalink to “映射的序列”">​</a></h3><p>你也可以創建一個包含映射的序列。對於人類排序數據的方式來説，這並不太常見，但對於計算機來説，這可能是一個重要的結構。</p><p>這裏有一個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>-</span></span>
<span class="line"><span>  CPU: AMD</span></span>
<span class="line"><span>  RAM: &#39;16 GB&#39;</span></span>
<span class="line"><span>-</span></span>
<span class="line"><span>  CPU: Intel</span></span>
<span class="line"><span>  RAM: &#39;16 GB&#39;</span></span></code></pre></div><p>對於 YAML，這可能是最不直觀的語法。我發現它在 Python 中呈現時更清晰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[{&quot;CPU&quot;: &quot;AMD&quot;, &quot;RAM&quot;: &quot;16 GB&quot;}, {&quot;CPU&quot;: &quot;Intel&quot;, &quot;RAM&quot;: &quot;16 GB&quot;}]</span></span></code></pre></div><p>方括號代表一個列表結構，這個列表包含兩個字典。每個字典都包含鍵值對。</p><h3 id="構建更好的-yaml" tabindex="-1">構建更好的 YAML <a class="header-anchor" href="#構建更好的-yaml" aria-label="Permalink to “構建更好的 YAML”">​</a></h3><p>現在你知道了 YAML 的兩個組成部分，以及它們如何被組合起來以表示複雜的數據結構。問題是：你要用 YAML 構建什麼？</p><p>和很多人一樣，我也使用 YAML 來編寫 Ansible 劇本。我還用它作為一種簡單的配置格式、作為 D&amp;D 的角色表、表示項目組織所需的目錄結構，等等。只要你能適應序列和映射的概念，你會發現 YAML 是一種很容易編寫、閲讀和（如果有合適的庫）解析的格式。</p>`,28)),i("p",null,[s[6]||(s[6]=a("如果你發現自己經常使用 YAML，請下載我們的 ",-1)),e(n,{href:"https://opensource.com/downloads/yaml-cheat-sheet"},{default:p(()=>[...s[5]||(s[5]=[a("YAML 速查表",-1)])]),_:1}),s[7]||(s[7]=a("，以幫助你直觀地瞭解基本數據結構及其組合，並幫助你記住一些額外的語法約定。通過一點點的練習，你會發現 YAML 真的和它看起來一樣簡單！",-1))]),s[25]||(s[25]=i("hr",null,null,-1)),i("p",null,[s[9]||(s[9]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/21/9/yaml-cheat-sheet"},{default:p(()=>[...s[8]||(s[8]=[a("https://opensource.com/article/21/9/yaml-cheat-sheet",-1)])]),_:1})]),i("p",null,[s[14]||(s[14]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/seth"},{default:p(()=>[...s[10]||(s[10]=[a("Seth Kenlon",-1)])]),_:1}),s[15]||(s[15]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[11]||(s[11]=[a("lujun9972",-1)])]),_:1}),s[16]||(s[16]=a(" 譯者：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1}),s[17]||(s[17]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[13]||(s[13]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[20]||(s[20]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[18]||(s[18]=[a("LCTT",-1)])]),_:1}),s[21]||(s[21]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[19]||(s[19]=[a("Linux中國",-1)])]),_:1}),s[22]||(s[22]=a(" 榮譽推出",-1))])])}const f=t(h,[["render",u]]);export{m as __pageData,f as default};
